def table(headers, rows, widths):
 t=d.add_table(rows=1, cols=len(headers)); t.alignment=WD_TABLE_ALIGNMENT.CENTER; t.autofit=False
 for c,w in zip(t.columns,widths): c.width=Cm(w)
 for c,tx in zip(t.rows[0].cells,headers): c.text=tx
 pr=t.rows[0]._tr.get_or_add_trPr(); pr.append(OxmlElement('w:tblHeader'))
 for row in rows:
  cells=t.add_row().cells
  for c,tx in zip(cells,row): c.text=str(tx)
 for i,r in enumerate(t.rows):
  pr=r._tr.get_or_add_trPr(); pr.append(OxmlElement('w:cantSplit'))
  for j,c in enumerate(r.cells):
   c.width=Cm(widths[j]); c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
   tcpr=c._tc.get_or_add_tcPr(); sh=OxmlElement('w:shd'); sh.set(qn('w:fill'),'E7EDF3' if i==0 else 'FFFFFF'); tcpr.append(sh)
   borders=OxmlElement('w:tcBorders')
   for edge in ['top','left','bottom','right']:
    el=OxmlElement('w:'+edge); el.set(qn('w:val'),'single'); el.set(qn('w:sz'),'4'); el.set(qn('w:color'),'D9D9D9'); borders.append(el)
   tcpr.append(borders)
   mar=OxmlElement('w:tcMar')
   for edge in ['top','left','bottom','right']:
    el=OxmlElement('w:'+edge); el.set(qn('w:w'),'85'); el.set(qn('w:type'),'dxa'); mar.append(el)
   tcpr.append(mar)
   for pp in c.paragraphs:
    pp.paragraph_format.space_after=Pt(3); pp.paragraph_format.space_before=Pt(3); pp.paragraph_format.line_spacing=1
    if j==0: pp.alignment=WD_ALIGN_PARAGRAPH.CENTER
    for rr in pp.runs: rr.font.size=Pt(10); rr.bold=(i==0)
 return t
